import{_ as p,a0 as o,w as d,s as h,I as e,x as a,a1 as n,A as t,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"iWant：一個去中心化的點對點共享文件的命令列工具 | LCTT x X-CMD","titleTemplate":false,"description":"iWant：一個去中心化的點對點共享文件的命令列工具 | LCTT (201904) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"iWant：一個去中心化的點對點共享文件的命令列工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"iWant：一個去中心化的點對點共享文件的命令列工具 | LCTT (201904) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201904/20170710 iWant - The Decentralized Peer To Peer File Sharing Commandline Application","title":"iWant：一個去中心化的點對點共享文件的命令列工具","tag":"201904","desc":""},"relativePath":"201904/20170710 iWant - The Decentralized Peer To Peer File Sharing Commandline Application.md","filePath":"[post].md"}'),r={name:"201904/20170710 iWant - The Decentralized Peer To Peer File Sharing Commandline Application.md"};function g(c,i,k,b,u,f){const s=o("Link");return d(),h("div",null,[i[23]||(i[23]=e("h1",{id:"iwant-一個去中心化的點對點共享文件的命令列工具",tabindex:"-1"},[a("iWant：一個去中心化的點對點共享文件的命令列工具 "),e("a",{class:"header-anchor",href:"#iwant-一個去中心化的點對點共享文件的命令列工具","aria-label":"Permalink to “iWant：一個去中心化的點對點共享文件的命令列工具”"},"​")],-1)),i[24]||(i[24]=e("p",null,[e("img",{src:"https://www.ostechnix.com/wp-content/uploads/2017/07/p2p-720x340.jpg",alt:""})],-1)),e("p",null,[i[2]||(i[2]=a("不久之前，我們編寫了一個指南，內容是一個文件共享實用程序，名為 ",-1)),n(s,{href:"https://www.ostechnix.com/easy-fast-way-share-files-internet-command-line/"},{default:t(()=>[...i[0]||(i[0]=[a("transfer.sh",-1)])]),_:1}),i[3]||(i[3]=a("，它是一個免費的 Web 服務，允許你在 Internet 上輕鬆快速地共享文件，還有 ",-1)),n(s,{href:"https://www.ostechnix.com/psitransfer-simple-open-source-self-hosted-file-sharing-solution/"},{default:t(()=>[...i[1]||(i[1]=[a("PSiTransfer",-1)])]),_:1}),i[4]||(i[4]=a("，一個簡單的開源自託管文件共享解決方案。今天，我們將看到另一個名為 “iWant” 的文件共享實用程序。它是一個基於命令列的自由開源的去中心化點對點文件共享應用程序。",-1))]),i[25]||(i[25]=l('<p>你可能想知道，它與其它文件共享應用程序有什麼不同？以下是 iWant 的一些突出特點。</p><ul><li>它是一個命令列應用程序。這意味着你不需要消耗內存來加載 GUI 實用程序。你只需要一個終端。</li><li>它是去中心化的。這意味着你的數據不會在任何中心位置存儲。因此，不會因為中心點失敗而失敗。</li><li>iWant 允許中斷下載，你可以在以後隨時恢復。你不需要從頭開始下載，它會從你停止的位置恢復下載。</li><li>共享目錄中文件所作的任何更改（如刪除、添加、修改）都會立即反映在網絡中。</li><li>就像種子一樣，iWant 從多個節點下載文件。如果任何節點離開羣組或未能響應，它將繼續從另一個節點下載。</li><li>它是跨平台的，因此你可以在 GNU/Linux、MS Windows 或者 Mac OS X 中使用它。</li></ul><h3 id="安裝-iwant" tabindex="-1">安裝 iWant <a class="header-anchor" href="#安裝-iwant" aria-label="Permalink to “安裝 iWant”">​</a></h3><p>iWant 可以使用 PIP 包管理器輕鬆安裝。確保你在 Linux 發行版中安裝了 pip。如果尚未安裝，參考以下指南。</p>',4)),e("p",null,[n(s,{href:"https://www.ostechnix.com/manage-python-packages-using-pip/"},{default:t(()=>[...i[5]||(i[5]=[a("如何使用 Pip 管理 Python 包",-1)])]),_:1})]),i[26]||(i[26]=l(`<p>安裝 pip 後，確保你有以下依賴項：</p><ul><li>libffi-dev</li><li>libssl-dev</li></ul><p>比如説，在 Ubuntu 上，你可以使用以下命令安裝這些依賴項：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt-get install libffi-dev libssl-dev</span></span></code></pre></div><p>安裝完所有依賴項後，使用以下命令安裝 iWant：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo pip install iwant</span></span></code></pre></div><p>現在我們的系統中已經有了 iWant，讓我們來看看如何使用它來通過網絡傳輸文件。</p><h3 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to “用法”">​</a></h3><p>首先，使用以下命令啓動 iWant 服務器：</p><p>（LCTT 譯註：雖然這個軟件是叫 iWant，但是其命令名為 <code>iwanto</code>，另外這個軟件至少一年沒有更新了。）</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ iwanto start</span></span></code></pre></div><p>第一次啓動時，iWant 會詢問想要分享和下載文件夾的位置，所以需要輸入兩個文件夾的位置。然後，選擇要使用的網卡。</p><p>示例輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Shared/Download folder details looks empty..</span></span>
<span class="line"><span>Note: Shared and Download folder cannot be the same</span></span>
<span class="line"><span>SHARED FOLDER(absolute path):/home/sk/myshare</span></span>
<span class="line"><span>DOWNLOAD FOLDER(absolute path):/home/sk/mydownloads</span></span>
<span class="line"><span>Network interface available</span></span>
<span class="line"><span>1. lo =&gt; 127.0.0.1</span></span>
<span class="line"><span>2. enp0s3 =&gt; 192.168.43.2</span></span>
<span class="line"><span>Enter index of the interface:2</span></span>
<span class="line"><span>now scanning /home/sk/myshare</span></span>
<span class="line"><span>[Adding] /home/sk/myshare 0.0</span></span>
<span class="line"><span>Updating Leader 56f6d5e8-654e-11e7-93c8-08002712f8c1</span></span>
<span class="line"><span>[Adding] /home/sk/myshare 0.0</span></span>
<span class="line"><span>connecting to 192.168.43.2:1235 for hashdump</span></span></code></pre></div><p>如果你看到類似上面的輸出，你可以立即開始使用 iWant 了。</p><p>同樣，在網絡中的所有系統上啓動 iWant 服務，指定有效的分享和下載文件夾的位置，並選擇合適的網卡。</p><p>iWant 服務將繼續在當前終端窗口中運行，直到你按下 <code>CTRL+C</code> 退出為止。你需要打開一個新選項卡或新的終端窗口來使用 iWant。</p><p>iWant 的用法非常簡單，它的命令很少，如下所示。</p><ul><li><code>iwanto start</code> – 啓動 iWant 服務。</li><li><code>iwanto search &lt;name&gt;</code> – 查找文件。</li><li><code>iwanto download &lt;hash&gt;</code> – 下載一個文件。</li><li><code>iwanto share &lt;path&gt;</code> – 更改共享文件夾的位置。</li><li><code>iwanto download to &lt;destination&gt;</code> – 更改下載文件夾位置。</li><li><code>iwanto view config</code> – 查看共享和下載文件夾。</li><li><code>iwanto –version</code> – 顯示 iWant 版本。</li><li><code>iwanto -h</code> – 顯示幫助信息。</li></ul><p>讓我向你展示一些例子。</p><h4 id="查找文件" tabindex="-1">查找文件 <a class="header-anchor" href="#查找文件" aria-label="Permalink to “查找文件”">​</a></h4><p>要查找一個文件，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ iwanto search &lt;filename&gt;</span></span></code></pre></div><p>請注意，你無需指定確切的名稱。</p><p>示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ iwanto search command</span></span></code></pre></div><p>上面的命令將搜索包含 “command” 字符串的所有文件。</p><p>我的 Ubuntu 系統會輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Filename Size Checksum</span></span>
<span class="line"><span>------------------------------------------- ------- --------------------------------</span></span>
<span class="line"><span>/home/sk/myshare/THE LINUX COMMAND LINE.pdf 3.85757 efded6cc6f34a3d107c67c2300459911</span></span></code></pre></div><h4 id="下載文件" tabindex="-1">下載文件 <a class="header-anchor" href="#下載文件" aria-label="Permalink to “下載文件”">​</a></h4><p>你可以在你的網絡上的任何系統下載文件。要下載文件，只需提供文件的哈希（校驗和），如下所示。你可以使用 <code>iwanto search</code> 命令獲取共享的哈希值。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ iwanto download efded6cc6f34a3d107c67c2300459911</span></span></code></pre></div><p>文件將保存在你的下載位置，在本文中是 <code>/home/sk/mydownloads/</code> 位置。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Filename: /home/sk/mydownloads/THE LINUX COMMAND LINE.pdf</span></span>
<span class="line"><span>Size: 3.857569 MB</span></span></code></pre></div><h4 id="查看配置" tabindex="-1">查看配置 <a class="header-anchor" href="#查看配置" aria-label="Permalink to “查看配置”">​</a></h4><p>要查看配置，例如共享和下載文件夾的位置，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ iwanto view config</span></span></code></pre></div><p>示例輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Shared folder:/home/sk/myshare</span></span>
<span class="line"><span>Download folder:/home/sk/mydownloads</span></span></code></pre></div><h4 id="更改共享和下載文件夾的位置" tabindex="-1">更改共享和下載文件夾的位置 <a class="header-anchor" href="#更改共享和下載文件夾的位置" aria-label="Permalink to “更改共享和下載文件夾的位置”">​</a></h4><p>你可以更改共享文件夾和下載文件夾。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ iwanto share /home/sk/ostechnix</span></span></code></pre></div><p>現在，共享位置已更改為 <code>/home/sk/ostechnix</code>。</p><p>同樣，你可以使用以下命令更改下載位置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ iwanto download to /home/sk/Downloads</span></span></code></pre></div><p>要查看所做的更改，運行命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ iwanto view config</span></span></code></pre></div><h4 id="停止-iwant" tabindex="-1">停止 iWant <a class="header-anchor" href="#停止-iwant" aria-label="Permalink to “停止 iWant”">​</a></h4><p>一旦你不想用 iWant 了，可以按下 <code>CTRL+C</code> 退出。</p><p>如果它不起作用，那可能是由於防火牆或你的路由器不支持多播。你可以在 <code>~/.iwant/.iwant.log</code> 文件中查看所有日誌。有關更多詳細信息，參閲最後提供的項目的 GitHub 頁面。</p><p>差不多就是全部了。希望這個工具有所幫助。下次我會帶着另一個有趣的指南再次來到這裏。</p><p>乾杯！</p><h3 id="資源" tabindex="-1">資源 <a class="header-anchor" href="#資源" aria-label="Permalink to “資源”">​</a></h3>`,53)),e("p",null,[i[7]||(i[7]=a("-",-1)),n(s,{href:"https://github.com/nirvik/iWant"},{default:t(()=>[...i[6]||(i[6]=[a("iWant GitHub",-1)])]),_:1})]),i[27]||(i[27]=e("hr",null,null,-1)),e("p",null,[i[9]||(i[9]=a("via: ",-1)),n(s,{href:"https://www.ostechnix.com/iwant-decentralized-peer-peer-file-sharing-commandline-application/"},{default:t(()=>[...i[8]||(i[8]=[a("https://www.ostechnix.com/iwant-decentralized-peer-peer-file-sharing-commandline-application/",-1)])]),_:1})]),e("p",null,[i[14]||(i[14]=a("作者：",-1)),n(s,{href:"https://www.ostechnix.com/author/sk/"},{default:t(()=>[...i[10]||(i[10]=[a("SK",-1)])]),_:1}),i[15]||(i[15]=a(" 選題：",-1)),n(s,{href:"https://github.com/lujun9972"},{default:t(()=>[...i[11]||(i[11]=[a("lujun9972",-1)])]),_:1}),i[16]||(i[16]=a(" 譯者：",-1)),n(s,{href:"https://github.com/MjSeven"},{default:t(()=>[...i[12]||(i[12]=[a("MjSeven",-1)])]),_:1}),i[17]||(i[17]=a(" 校對：",-1)),n(s,{href:"https://github.com/wxy"},{default:t(()=>[...i[13]||(i[13]=[a("wxy",-1)])]),_:1})]),e("p",null,[i[20]||(i[20]=a("本文由 ",-1)),n(s,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...i[18]||(i[18]=[a("LCTT",-1)])]),_:1}),i[21]||(i[21]=a(" 原創編譯，",-1)),n(s,{href:"https://linux.cn/"},{default:t(()=>[...i[19]||(i[19]=[a("Linux中國",-1)])]),_:1}),i[22]||(i[22]=a(" 榮譽推出",-1))])])}const C=p(r,[["render",g]]);export{y as __pageData,C as default};
